import { gameCatalog } from './game-data.js';
const id=document.body.dataset.game;
const meta=gameCatalog.find(g=>g.id===id);
const canvas=document.getElementById('game-canvas'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('game-overlay'),overlayTitle=document.getElementById('overlay-title'),overlayText=document.getElementById('overlay-text'),startButton=document.getElementById('start-game');
const state={running:false,started:false,ended:false,keys:new Set(),pointer:{x:0,y:0,down:false}};
let game,lastTime=0,muted=true,audioContext,records={},remember=false;
function validRecords(value){const result={};if(!value||typeof value!=='object'||Array.isArray(value))return result;for(const g of gameCatalog){const score=Number(value[g.id]?.score);if(Number.isFinite(score)&&score>0)result[g.id]={score:Math.round(score)};}return result;}
function mergeRecords(a,b){const left=validRecords(a),right=validRecords(b),merged={};for(const g of gameCatalog){const score=Math.max(left[g.id]?.score||0,right[g.id]?.score||0);if(score>0)merged[g.id]={score};}return merged;}
try{remember=localStorage.getItem('apina-score-preference')==='yes';if(remember)records=validRecords(JSON.parse(localStorage.getItem('apina-game-records')||'{}'));}catch{}
const best=document.getElementById('best-score');
function displayBest(){best.textContent=Number(records[id]?.score||0).toLocaleString();}
function announce(text){document.getElementById('game-announcement').textContent=text;}
function sound(kind){if(muted||!audioContext)return;try{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=kind==='hit'?'triangle':'sine';o.frequency.setValueAtTime(kind==='win'?660:kind==='hit'?120:390,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='win'?990:kind==='hit'?60:550,audioContext.currentTime+.12);g.gain.setValueAtTime(.07,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.18);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.19);}catch{}}
function hud(values){const el=document.getElementById('game-stats');const signature=JSON.stringify(values);if(el.dataset.signature===signature)return;el.dataset.signature=signature;el.replaceChildren(...Object.entries(values).map(([label,value])=>{const item=document.createElement('div'),l=document.createElement('span'),v=document.createElement('strong');l.textContent=label;v.textContent=String(value);item.append(l,v);return item;}));}
function end(score,title,detail){if(state.ended)return;state.running=false;state.ended=true;clearInput();const n=Math.max(0,Math.round(Number(score)||0));if(n>Number(records[id]?.score||0)){records[id]={score:n};if(remember)try{const existing=JSON.parse(localStorage.getItem('apina-game-records')||'{}');records=mergeRecords(existing,records);localStorage.setItem('apina-game-records',JSON.stringify(records));}catch{announce('This score is available for this visit; browser storage is unavailable.');}displayBest();}overlayTitle.textContent=title||'Run complete';overlayText.textContent=detail||`Score: ${n.toLocaleString()}`;startButton.textContent='Play again';overlay.hidden=false;document.getElementById('pause-game').textContent='Pause';announce(`${overlayTitle.textContent}. ${overlayText.textContent}`);startButton.focus({preventScroll:true});}
const options=Object.fromEntries([...document.querySelectorAll('[data-game-option]')].map(el=>[el.dataset.gameOption,el.value]));
const api={canvas,ctx,width:960,height:600,options,input:{keys:state.keys,pointer:state.pointer},hud,end,sound,setControlValue:(name,value)=>{const el=document.querySelector(`[data-game-option="${name}"]`);if(el){el.value=value;options[name]=String(value);}},setHint:text=>{document.getElementById('live-hint').textContent=text;}};
document.querySelectorAll('[data-game-option]').forEach(el=>el.addEventListener(el.type==='range'?'input':'change',()=>{options[el.dataset.gameOption]=el.value;if(el.type==='range'){game?.setPower?.(Number(el.value));return;}if(!game)return;state.running=false;state.started=false;state.ended=false;clearInput();game.reset();overlayTitle.textContent=meta.name;overlayText.textContent=meta.controls;startButton.textContent='Start game';overlay.hidden=false;document.getElementById('pause-game').textContent='Pause';}));
function clearInput(){state.keys.clear();state.pointer.down=false;game?.pointerCancel?.();document.querySelectorAll('[data-key]').forEach(b=>b.classList.remove('pressed'));}
function resumeAudio(){if(muted)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();}catch{}}
function start(){if(!game)return;resumeAudio();if(!state.started||state.ended){state.ended=false;game.reset();state.started=true;}state.running=true;overlay.hidden=true;document.getElementById('pause-game').textContent='Pause';canvas.focus({preventScroll:true});lastTime=performance.now();}
function pause(){if(!state.running)return;state.running=false;clearInput();overlayTitle.textContent='Paused';overlayText.textContent='Your game will continue from here.';startButton.textContent='Resume';overlay.hidden=false;document.getElementById('pause-game').textContent='Resume';}
startButton.addEventListener('click',start);
document.getElementById('pause-game').addEventListener('click',()=>state.running?pause():state.started&&!state.ended?start():null);
document.getElementById('restart-game').addEventListener('click',()=>{if(!game)return;state.ended=false;state.started=true;clearInput();game.reset();state.running=true;overlay.hidden=true;document.getElementById('pause-game').textContent='Pause';resumeAudio();canvas.focus({preventScroll:true});});
document.getElementById('sound-game').addEventListener('click',event=>{muted=!muted;event.currentTarget.textContent=muted?'Sound off':'Sound on';event.currentTarget.setAttribute('aria-pressed',String(!muted));resumeAudio();});
document.getElementById('fullscreen-game').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.getElementById('game-shell').requestFullscreen();}catch{announce('Fullscreen is unavailable in this browser.');}});
function coords(event){const r=canvas.getBoundingClientRect();return{x:(event.clientX-r.left)*960/r.width,y:(event.clientY-r.top)*600/r.height};}
canvas.addEventListener('pointerdown',event=>{if(!state.running)return;event.preventDefault();canvas.focus({preventScroll:true});canvas.setPointerCapture(event.pointerId);Object.assign(state.pointer,coords(event),{down:true});game.pointerDown?.(state.pointer.x,state.pointer.y);});
canvas.addEventListener('pointermove',event=>{Object.assign(state.pointer,coords(event));if(state.running)game.pointerMove?.(state.pointer.x,state.pointer.y);});
canvas.addEventListener('pointerup',event=>{Object.assign(state.pointer,coords(event),{down:false});if(state.running)game.pointerUp?.(state.pointer.x,state.pointer.y);});
canvas.addEventListener('pointercancel',()=>{state.pointer.down=false;game?.pointerCancel?.();});
function keyNames(key){return key===' '?['Space',' ']:[key,key.length===1?key.toLowerCase():key];}
window.addEventListener('keydown',event=>{if(event.key==='Escape'){pause();return;}if(!state.running||event.target.closest('input,textarea,select,button,a'))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(event.key))event.preventDefault();keyNames(event.key).forEach(k=>state.keys.add(k));if(!event.repeat||(['orbit','pool'].includes(id)&&event.key.startsWith('Arrow')))game.keyDown?.(event.key===' '?'Space':event.key);});
window.addEventListener('keyup',event=>keyNames(event.key).forEach(k=>state.keys.delete(k)));
window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
document.querySelectorAll('[data-key]').forEach(button=>{button.addEventListener('pointerdown',event=>{if(!state.running)return;event.preventDefault();button.setPointerCapture(event.pointerId);const key=button.dataset.key;state.keys.add(key);button.classList.add('pressed');game.keyDown?.(key);});const up=()=>{state.keys.delete(button.dataset.key);button.classList.remove('pressed');};button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('lostpointercapture',up);});
const rememberBox=document.getElementById('remember-scores');
function scorePreferenceUI(){rememberBox.checked=remember;document.getElementById('best-note').textContent=remember?'Saved on this device. Higher is better.':'For this visit. Higher is better.';}
rememberBox.addEventListener('change',()=>{remember=rememberBox.checked;try{if(remember){const existing=JSON.parse(localStorage.getItem('apina-game-records')||'{}');records=mergeRecords(existing,records);localStorage.setItem('apina-game-records',JSON.stringify(records));localStorage.setItem('apina-score-preference','yes');}else{localStorage.removeItem('apina-score-preference');localStorage.removeItem('apina-game-records');}scorePreferenceUI();displayBest();}catch{remember=false;try{localStorage.removeItem('apina-score-preference');localStorage.removeItem('apina-game-records');}catch{}scorePreferenceUI();announce('Score storage could not be updated. Use browser site-data settings if needed; this visit will not save scores.');}});
window.addEventListener('storage',event=>{if(!['apina-game-records','apina-score-preference',null].includes(event.key))return;try{remember=localStorage.getItem('apina-score-preference')==='yes';records=remember?validRecords(JSON.parse(localStorage.getItem('apina-game-records')||'{}')):{};}catch{records={};remember=false;}displayBest();scorePreferenceUI();});
const favorite=document.getElementById('favorite-game');function savedState(){try{return new Set(JSON.parse(localStorage.getItem('apina-favorites')||'[]'));}catch{return new Set();}}
function updateFavorite(){const active=savedState().has(id);favorite.textContent=active?'♥ Saved':'♡ Save game';favorite.setAttribute('aria-pressed',String(active));}
favorite.addEventListener('click',()=>{const saved=savedState();saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('apina-favorites',JSON.stringify([...saved]));updateFavorite();}catch{announce('Favorites cannot be saved because browser storage is unavailable.');}});window.addEventListener('storage',updateFavorite);
document.getElementById('random-game').addEventListener('click',()=>{const choices=gameCatalog.filter(g=>g.id!==id);location.href=`${choices[Math.floor(Math.random()*choices.length)].slug}.html`;});
function frame(now){const dt=Math.min(.035,(now-lastTime)/1000||0);lastTime=now;if(game){if(state.running)game.update(dt);ctx.save();game.draw(ctx);ctx.restore();}requestAnimationFrame(frame);}
displayBest();updateFavorite();scorePreferenceUI();
try{const module=await import(`./games/${id}.js`);game=module.default(api);game.reset();startButton.disabled=false;requestAnimationFrame(frame);}catch(error){console.error(error);overlayTitle.textContent='Could not load the game';overlayText.textContent='Try refreshing this page. If the problem continues, return to the collection.';startButton.hidden=true;}
